"""Ordered notification log."""


class EventLog:
    def __init__(self):
        self._items = []

    def emit(self, *notification):
        self._items.append(tuple(notification))

    def all(self):
        return list(self._items)

    def to_list(self):
        return [list(n) for n in self._items]

    @classmethod
    def from_list(cls, rows):
        log = cls()
        for row in rows:
            if not isinstance(row, list) or not row or not isinstance(row[0], str):
                raise ValueError("bad notification")
            log._items.append(tuple(row))
        return log
