"""Depot: multi-warehouse inventory and cash ledger."""
import copy
import decimal
import json
from decimal import Decimal

from events import EventLog
from money import Money, load_data, list_price as _list_price, scale_pct
from suppliers import Suppliers


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


_MODES = {getattr(decimal, n) for n in dir(decimal) if n.startswith("ROUND_")}
_STATE = ("day", "items", "lots", "shipped", "returned", "fired",
          "log", "money", "sup")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, *,
                 late_penalty_pct=None, returned_perishables=None):
        if rounding_mode not in _MODES:
            raise DepotError("INVALID_ARGUMENT")
        if not warehouses or len(set(warehouses)) != len(warehouses):
            raise DepotError("INVALID_ARGUMENT")
        for w in warehouses:
            if w not in capacities or not _is_int(capacities[w]) or capacities[w] < 0:
                raise DepotError("INVALID_ARGUMENT")
        if not _is_int(opening_cash):
            raise DepotError("INVALID_ARGUMENT")
        if late_penalty_pct is not None and not (0 <= Decimal(str(late_penalty_pct)) <= 100):
            raise DepotError("INVALID_ARGUMENT")
        if returned_perishables not in (None, "restock", "discard"):
            raise DepotError("INVALID_ARGUMENT")
        data = load_data()
        self.markup = data["markup"]
        self.bulk_threshold = data["bulk_threshold"]
        self.bulk_pct = data["bulk_discount_pct"]
        self.storage = data["storage_cents_per_unit_day"]
        self.transfer_cents = data["transfer_credit_cents_per_unit"]
        self.mode = rounding_mode
        self.warehouses = list(warehouses)
        self.capacities = {w: capacities[w] for w in warehouses}
        self.late_penalty_pct = late_penalty_pct
        self.returned_perishables = returned_perishables

        self.day = 0
        self.items = {}
        self.lots = {}       # sku -> wh -> [[day, qty], ...] oldest first
        self.shipped = {}
        self.returned = {}
        self.fired = set()   # (sku, wh) with REORDER already emitted
        self.log = EventLog()
        self.money = Money(opening_cash)
        self.sup = Suppliers()
        self._undo = None
        self._blocked = False

    # ---- plumbing -------------------------------------------------------
    def _capture(self):
        return copy.deepcopy({n: getattr(self, n) for n in _STATE})

    def _restore(self, snap):
        for n, v in snap.items():
            setattr(self, n, v)

    def _run(self, fn, block=False):
        snap = self._capture()
        try:
            result = fn()
        except BaseException:
            self._restore(snap)
            raise
        if block:
            self._undo, self._blocked = None, True
        else:
            self._undo, self._blocked = snap, False
        return result

    def _sku(self, sku):
        if sku not in self.items:
            raise DepotError("UNKNOWN_SKU")

    def _wh(self, wh):
        if wh not in self.capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _qty(qty):
        if not _is_int(qty) or qty <= 0:
            raise DepotError("INVALID_QTY")

    @staticmethod
    def _price(price):
        if not _is_int(price) or price < 0:
            raise DepotError("INVALID_ARGUMENT")

    def _stock(self, sku, wh):
        return sum(q for _, q in self.lots[sku].get(wh, []))

    def _units(self, wh):
        return sum(self._stock(s, wh) for s in self.items)

    def _total_units(self):
        return sum(self._units(w) for w in self.warehouses)

    def _check_capacity(self, wh, qty):
        if self._units(wh) + qty > self.capacities[wh]:
            raise DepotError("CAPACITY")

    def _rearm(self, sku, wh):
        if self._stock(sku, wh) > self.items[sku]["reorder_level"]:
            self.fired.discard((sku, wh))

    def _put_lot(self, sku, wh, day, qty):
        lots = self.lots[sku].setdefault(wh, [])
        lots.append([day, qty])
        lots.sort(key=lambda l: l[0])
        self._rearm(sku, wh)

    def _take(self, sku, wh, qty):
        lots = self.lots[sku].get(wh, [])
        taken = []
        need = qty
        while need > 0:
            lot = lots[0]
            n = min(lot[1], need)
            taken.append((lot[0], n))
            lot[1] -= n
            need -= n
            if lot[1] == 0:
                lots.pop(0)
        return taken

    # ---- inventory ------------------------------------------------------
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        def op():
            if not _is_int(unit_cost) or unit_cost <= 0:
                raise DepotError("INVALID_ARGUMENT")
            if not _is_int(reorder_level) or reorder_level < 0:
                raise DepotError("INVALID_ARGUMENT")
            if shelf_life_days is not None and (not _is_int(shelf_life_days) or shelf_life_days < 1):
                raise DepotError("INVALID_ARGUMENT")
            if sku in self.items:
                raise DepotError("DUPLICATE_SKU")
            self.items[sku] = {"unit_cost": unit_cost, "reorder_level": reorder_level,
                               "shelf_life_days": shelf_life_days}
            self.lots[sku] = {}
            self.shipped[sku] = 0
            self.returned[sku] = 0
        self._run(op)

    def _receive(self, sku, qty, wh):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if self.money.cash < 0:
            raise DepotError("OVERDRAWN")
        self._check_capacity(wh, qty)
        cost = self.items[sku]["unit_cost"] * qty
        if self.money.cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self.money.adjust(-cost, self.log)
        self._put_lot(sku, wh, self.day, qty)

    def receive(self, sku, qty, wh):
        self._run(lambda: self._receive(sku, qty, wh))

    def receive_bulk(self, receipts):
        def op():
            for sku, qty, wh in receipts:
                self._receive(sku, qty, wh)
        self._run(op)

    def ship(self, sku, qty, wh, price):
        def op():
            self._sku(sku)
            self._wh(wh)
            self._qty(qty)
            self._price(price)
            if self._stock(sku, wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            unit = price
            if qty >= self.bulk_threshold:
                unit = scale_pct(price, 100 - Decimal(str(self.bulk_pct)), self.mode)
            self._take(sku, wh, qty)
            self.shipped[sku] += qty
            self.money.record_shipped(self.day, qty)
            self.money.adjust(unit * qty, self.log)
            if (self._stock(sku, wh) <= self.items[sku]["reorder_level"]
                    and (sku, wh) not in self.fired):
                self.fired.add((sku, wh))
                self.log.emit("REORDER", sku, wh)
        self._run(op)

    def list_price(self, sku):
        self._sku(sku)
        return _list_price(self.items[sku]["unit_cost"], self.markup, self.mode)

    def transfer(self, sku, qty, from_wh, to_wh):
        def op():
            self._sku(sku)
            self._wh(from_wh)
            self._wh(to_wh)
            self._qty(qty)
            if from_wh == to_wh:
                raise DepotError("INVALID_ARGUMENT")
            if self._stock(sku, from_wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            self._check_capacity(to_wh, qty)
            taken = self._take(sku, from_wh, qty)
            for d, n in taken:
                self._put_lot(sku, to_wh, d, n)
            self._rearm(sku, from_wh)
            self.money.adjust(-self.transfer_cents * qty, self.log)
        self._run(op)

    def return_goods(self, sku, qty, wh, price):
        def op():
            self._sku(sku)
            self._wh(wh)
            self._qty(qty)
            self._price(price)
            if self.returned[sku] + qty > self.shipped[sku]:
                raise DepotError("RETURN_EXCEEDS")
            perishable = self.items[sku]["shelf_life_days"] is not None
            restock = True
            if perishable:
                if self.returned_perishables is None:
                    raise DepotError("RETURN_POLICY_UNSET")
                restock = self.returned_perishables == "restock"
            if restock:
                self._check_capacity(wh, qty)
            self.returned[sku] += qty
            if restock:
                self._put_lot(sku, wh, self.day, qty)
            self.money.adjust(-price * qty, self.log)
        self._run(op)

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._wh(wh)
            return self._stock(sku, wh)
        return sum(self._stock(sku, w) for w in self.warehouses)

    def report(self):
        rows = []
        for sku in sorted(self.items):
            for wh in sorted(self.warehouses):
                u = self._stock(sku, wh)
                if u > 0:
                    rows.append((sku, wh, u, u * self.items[sku]["unit_cost"]))
        return rows

    def audit(self, counts):
        def op():
            if not counts:
                raise DepotError("EMPTY_AUDIT")
            for sku, wh in counts:
                self._sku(sku)
                self._wh(wh)
            for (sku, wh) in sorted(counts):
                ledger = self._stock(sku, wh)
                if ledger != counts[(sku, wh)]:
                    self.log.emit("AUDIT_MISMATCH", sku, wh, ledger, counts[(sku, wh)])
        self._run(op)

    # ---- time -----------------------------------------------------------
    def advance_day(self):
        def op():
            units = self._total_units()
            self.money.held_log[self.day] = units
            self.money.adjust(-units * self.storage, self.log, emit=False)
            self.day += 1
            for sku in sorted(self.items):
                shelf = self.items[sku]["shelf_life_days"]
                if shelf is None:
                    continue
                for wh in sorted(self.lots[sku]):
                    lots = self.lots[sku][wh]
                    expired = sum(q for d, q in lots if self.day - d > shelf)
                    if expired:
                        self.lots[sku][wh] = [l for l in lots if self.day - l[0] <= shelf]
                        self.log.emit("EXPIRY", sku, wh, expired)
                        self._rearm(sku, wh)
            self.money.check(self.log)
        self._run(op, block=True)

    # ---- suppliers ------------------------------------------------------
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        def op():
            self._sku(sku)
            self._qty(qty)
            if not _is_int(due_day):
                raise DepotError("INVALID_ARGUMENT")
            target = self.warehouses[0] if wh is None else wh
            self._wh(target)
            if self.sup.suspended(supplier):
                raise DepotError("SUPPLIER_SUSPENDED")
            self.sup.ensure(supplier)
            return self.sup.add_order(supplier, sku, qty, due_day, target)
        return self._run(op)

