"""Seeded demand simulation."""
import random

from money import load_data


def simulate(days, seed):
    demand = load_data()["demand"]
    rng = random.Random(seed)
    skus = sorted(demand)
    result = []
    for _ in range(days):
        orders = []
        for sku in skus:
            qty = rng.randint(demand[sku]["min"], demand[sku]["max"])
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
